    parse_frame(app_rx_buf[app_rx_rp], app_rx_len[app_rx_rp], out_cmd);

    // 移动读指针
    app_rx_rp = (app_rx_rp + 1) % APP_RX_BUF_NUM;

    // 返回解析结果是否有效（由 parse_frame 填充 out_cmd->valid）
    return out_cmd->valid;
